export function extraMissions(ctx){const {state,boardId,pair,notebook}=ctx;const measured=(a,b,mode='voltage',power=true,drive=null)=>state.red===a&&state.black===b&&state.mode===mode&&state.power===power&&(!drive||state.drive===drive);let list=[];function add(board,title,text,hint,check,success,extra={}){list.push({board,title,text,hint,check,success,tag:`${String(list.length+9).padStart(2,'0')} · PRÁCTICA`,...extra});}
add('mosfet','Marcar alimentación y retorno','Marca VCC y GND con dos colores diferentes. Mantén visibles ambas redes.','Usa Marcar red y el selector de color; toca cada red.',()=>notebook.data.nets.VCC&&notebook.data.nets.GND&&notebook.data.nets.VCC!==notebook.data.nets.GND,'Dos colores separan alimentación y retorno y evitan confundirlos al cambiar de cara.');
add('mosfet','Marcar un tramo de CONTROL','Marca al menos un tramo individual de CONTROL.','Activa Marcar tramo y toca una pista; también puedes usar Tramos por capa.',()=>Object.keys(notebook.data.segments).some(k=>k.startsWith('CONTROL:')),'Has separado un tramo físico de la red completa: ambos conceptos son útiles.');
add('mosfet','Guardar un recorrido por pads','Añade estos hitos en orden: JP5.3, Q1.1 y R1.P$2.','Activa Añadir hito y usa la lista de contactos de CONTROL.',()=>['JP5.3','Q1.1','R1.P$2'].every((p,i)=>notebook.data.points.slice(-3)[i]?.id===p),'El recorrido une el conector de mando, la puerta y su pull-down; todo pertenece a CONTROL.');
add('mosfet','Medir la resistencia pull-down','Fuente apagada: mide R1 entre sus dos terminales con el modo Ω.','Roja R1.P$2; negra R1.P$1. Espera 10 kΩ.',()=>measured('R1.P$2','R1.P$1','resistance',false),'R1 conecta CONTROL con GND y evita que la puerta quede sin referencia.');
add('mosfet','Una resistencia abierta','Activa la avería R1 abierta. Con la fuente apagada mide R1 en Ω.','Elige R1 abierta y mide sus extremos. El camino resistivo desaparece.',()=>state.fault==='rOpen'&&measured('R1.P$2','R1.P$1','resistance',false),'OL es coherente con R1 abierta dentro del modelo. Con un mando externo activo la puerta todavía puede funcionar.');
add('mosfet','Invertir las puntas','Activa la fuente y mide GND respecto a VCC: roja JP5.2, negra JP5.1.','Una lectura negativa no implica tensión de alimentación negativa.',()=>measured('JP5.2','JP5.1'),'−5 V refleja la polaridad de las puntas. El circuito no ha cambiado.');
add('mosfet','Caída sobre la carga externa','Con fuente y CONTROL altos, mide VCC respecto al drenador: roja JP5.1, negra Q1.2.','La carga se conecta entre VCC y HIGH-CURRENT.',()=>measured('JP5.1','Q1.2','voltage',true,'high'),'Casi 5 V caen sobre la carga; la caída del MOSFET encendido es pequeña.');
add('mosfet','Anotar una medida con sentido','Anota una lectura de tensión entre Q1.1 y Q1.3, con fuente y mando altos.','Pulsa Anotar esta medición después de colocar las puntas.',()=>notebook.data.readings.some(r=>r.red==='Q1.1'&&r.black==='Q1.3'&&r.mode==='voltage'&&r.power&&r.drive==='high'),'Tu registro conserva los puntos, el modo, el mando y la avería, además de la cifra.');
add('logic','Distinguir las dos alimentaciones','Marca LV y HV con colores diferentes.','LV es 3,3 V y HV es 5 V en el banco.',()=>notebook.data.nets.LV&&notebook.data.nets.HV&&notebook.data.nets.LV!==notebook.data.nets.HV,'Son dos alimentaciones distintas, aunque comparten GND.');
add('logic','Seguir el canal 2','Selecciona LV2 y localiza sus tres contactos.','Busca el transistor Q3 y la resistencia R2.',()=>state.net==='LV2','LV2 une JP1.5, Q3.2 y R2.2; no pertenece al canal de Q1.');
add('logic','Dos pull-up en serie al medir','Sin fuente, mide entre Q1.3 y Q3.3 en Ω.','Ambos lados HV llegan al mismo raíl por resistencias de 10 kΩ.',()=>measured('Q1.3','Q3.3','resistance',false),'El modelo resistivo da 20 kΩ a través de R4 y R10. Las uniones de los MOSFET no se incluyen en Ω.');
add('logic','Llevar un canal a nivel bajo','Alimenta, fuerza bajo el canal 1 y mide Q1.3 respecto a JP1.3.','JP1.3 es GND; el drenador del canal 1 es Q1.3.',()=>measured('Q1.3','JP1.3','voltage',true,'low'),'HV1 cae a 0 V en el modelo digital ideal cuando se fuerza bajo el canal 1.');
add('logic','Los canales no son la misma red','Con el canal 1 bajo, mide Q3.3 respecto a JP1.3.','Q3 pertenece al canal 2 y permanece liberado.',()=>measured('Q3.3','JP1.3','voltage',true,'low'),'HV2 permanece a 5 V; compartir alimentación no une las señales de los canales.');
add('logic','El mismo nodo en dos componentes','Apaga la fuente y comprueba continuidad entre R3.1 y Q1.1.','Ambos pertenecen a LV, que fija la puerta del MOSFET.',()=>!state.power&&state.mode==='continuity'&&pair('R3.1','Q1.1'),'La continuidad confirma la unión entre la alimentación LV y la puerta del transistor.');
add('divider','Dividir una tensión por dos','Activa fuente y entrada alta. Mide TP.OUT respecto a TP.GND.','Dos resistencias iguales de 10 kΩ forman el divisor.',()=>measured('TP.OUT','TP.GND','voltage',true,'high'),'La salida nominal es 2,5 V, sin carga externa y con resistencias ideales.');
add('divider','Seguir el retorno inferior','Marca la red GND y un tramo de GND en la cara inferior.','Voltea la placa. Los pads pasantes conectan R2 con el retorno inferior.',()=>notebook.data.nets.GND&&Object.keys(notebook.data.segments).some(k=>k.startsWith('GND:'))&&ctx.bottom(),'El retorno se enruta por abajo; no desaparece porque no esté en la cara de componentes.');
add('divider','Caída de tensión en R1','Con la entrada alta y fuente activa, mide R1.1 respecto a R1.2.','Mide entre extremos de la resistencia, no desde cada punto a masa.',()=>measured('R1.1','R1.2','voltage',true,'high'),'La caída en R1 es 2,5 V; su corriente es 2,5 V / 10 kΩ = 0,25 mA.');
add('divider','Qué ocurre si R2 se abre','Elige R2 abierta, activa fuente y entrada alta, mide OUT contra GND.','Sin R2 no hay caída DC apreciable en R1 si el voltímetro no carga.',()=>state.fault==='r2Open'&&measured('TP.OUT','TP.GND','voltage',true,'high'),'OUT sube a 5 V en el modelo ideal: el divisor ha perdido su rama inferior.');
add('rc','El condensador al inicio','Activa fuente y entrada alta. Lleva el tiempo a 0 ms y mide OUT respecto a GND.','C1 comienza descargado y conserva inicialmente 0 V.',()=>measured('TP.OUT','TP.GND','voltage',true,'high')&&state.time===0,'A t = 0+, la salida es 0 V. Toda la tensión inicial cae en R1.');
add('rc','Una constante de tiempo','Con fuente y entrada altas, mide OUT contra GND a 1 ms.','τ = 10 kΩ × 100 nF = 1 ms.',()=>measured('TP.OUT','TP.GND','voltage',true,'high')&&Math.abs(state.time-1)<.025,'A una constante de tiempo, la salida alcanza aproximadamente 3,161 V: el 63,2 % de 5 V.');
add('rc','Casi estabilizado','Mide OUT respecto a GND después de 5 ms, con entrada alta.','Cinco constantes de tiempo equivalen aproximadamente al 99,3 %.',()=>measured('TP.OUT','TP.GND','voltage',true,'high')&&state.time===5,'La salida es aproximadamente 4,966 V. El condensador tarda en cargarse, no bloquea indefinidamente la DC.');
add('rc','Un condensador en corto','Elige C1 en corto y mide OUT contra GND con fuente y entrada altas.','El cortocircuito fuerza el nodo de salida a masa.',()=>state.fault==='capShort'&&measured('TP.OUT','TP.GND','voltage',true,'high'),'OUT queda a 0 V; por R1 circulan 0,5 mA en este modelo.');
add('led','Calcular la corriente del LED','Con fuente y entrada altas, mide entre R1.1 y R1.2.','El LED se modela con caída de 2 V; R1 vale 1 kΩ.',()=>measured('R1.1','R1.2','voltage',true,'high'),'Sobre R1 caen 3 V: I = 3 V / 1 kΩ = 3 mA. No hace falta insertar un amperímetro.');
add('led','Distinguir un LED abierto','Selecciona D1 abierto. Mide D1.A respecto a D1.K con fuente y entrada altas.','Sin corriente no cae tensión en R1; toda aparece entre los terminales abiertos del LED.',()=>state.fault==='ledOpen'&&measured('D1.A','D1.K','voltage',true,'high'),'Aparecen 5 V entre A y K y no circula corriente: el LED abierto explica ambas observaciones.');
return list;}
